effect.shader:
void main(){
    vec4 src = texture2DCv(inputImg.texture, acScreenNorm);
    vec3 c = src.a>0.0? src.rgb/src.a : src.rgb;
    float l = dot(c, vec3(0.299,0.587,0.114));
    vec3 g = l<0.5 ? mix(low.rgb, mid.rgb, l*2.0) : mix(mid.rgb, high.rgb, (l-0.5)*2.0);
    gl_FragColor = vec4(mix(c,g,amount),1.0)*src.a;
}
